console.log(await reformer.formStart({ dir: "form", target: "renderer-json", specPath: "spec.md", task: `Сделай форму по спецификации из файла spec.md, но пошаговую — мастер вместо одной страницы:

- каждый раздел спецификации — отдельный шаг, в том же порядке, заголовок шага — название раздела;
- шаг «Компания» показывается только юрлицу;
- перейти на следующий шаг нельзя, пока поля текущего шага не заполнены верно;
- на последнем шаге вместо кнопки внизу страницы — кнопка мастера «Оформить заказ», она отправляет заказ так же, как описано в спецификации.

Стек: @reformer/renderer-json, разметка — документ JSON-схемы и реестр компонентов.` }))

const f = reformer.form();
f.field("customerType").options([{value:"person",label:"Физическое лицо"},{value:"company",label:"Юридическое лицо"}]).component("RadioGroup").initial("person").required("Выберите тип покупателя");
f.field("contact.lastName").required("Введите фамилию").minLength(2,"Минимум 2 символа");
f.field("contact.firstName").required("Введите имя").minLength(2,"Минимум 2 символа");
f.field("email").required("Введите email").email("Некорректный email");
f.field("phone").mask("+7 (999) 999-99-99").required("Введите телефон").pattern(/^\+7 \(\d{3}\) \d{3}-\d{2}-\d{2}$/,"Формат +7 (999) 999-99-99");
f.field("birthDate").type("date").required("Укажите дату рождения").rule("minAge(18)","Покупателю должно быть не меньше 18 лет").when(m=>m.customerType==="person");
f.field("company.name").required("Введите название организации").when(m=>m.customerType==="company");
f.field("company.inn").required("Введите ИНН").pattern(/^\d{10}$/,"ИНН — 10 цифр").check(m=>{const s=String(m.company.inn);return !/^\d{10}$/.test(s)||((Number(s[0])*2+Number(s[1])*4+Number(s[2])*10+Number(s[3])*3+Number(s[4])*5+Number(s[5])*9+Number(s[6])*4+Number(s[7])*6+Number(s[8])*8)%11)%10===Number(s[9])},"Неверная контрольная сумма ИНН").when(m=>m.customerType==="company");
f.field("deliveryMethod").options([{value:"pickup",label:"Самовывоз"},{value:"courier",label:"Курьер"},{value:"post",label:"Почта"}]).initial("pickup").required("Выберите способ получения");
f.field("deliveryAddress.city").required("Введите город").when(m=>m.deliveryMethod!=="pickup").disableWhen(m=>m.deliveryMethod==="pickup",{resetOnDisable:true});
f.field("deliveryAddress.street").required("Введите улицу").when(m=>m.deliveryMethod!=="pickup").disableWhen(m=>m.deliveryMethod==="pickup",{resetOnDisable:true});
f.field("deliveryAddress.house").required("Введите дом").when(m=>m.deliveryMethod!=="pickup").disableWhen(m=>m.deliveryMethod==="pickup",{resetOnDisable:true});
f.field("deliveryDate").component("DatePicker").required("Выберите дату доставки").future("Дата доставки — не раньше завтрашнего дня").when(m=>m.deliveryMethod==="courier").showWhen(m=>m.deliveryMethod==="courier").resetWhen(m=>m.deliveryMethod!=="courier");
f.field("billingSame").initial(true);
for (const [k,l] of [["city","Введите город"],["street","Введите улицу"],["house","Введите дом"]]) f.field("billingAddress."+k).required(l).when(m=>!m.billingSame);
f.field("billingAddress").copyFrom("deliveryAddress", m=>m.billingSame).disableWhen(m=>m.billingSame);
f.field("subtotal").readonly().compute(m=>m.items.reduce((s,r)=>s+(Number(r.quantity)||0)*(Number(r.price)||0),0));
f.field("promoCode").transform(v=>(v??"").toUpperCase()).asyncCheck(v=>!v||v==="SALE10"||v==="SALE20",{delay:300,message:"Промокод не найден"});
f.field("discount").component("Slider").min(0,"Скидка не может быть отрицательной").max(30,"Скидка не больше 30%").initial(0).enableWhen(m=>m.customerType==="company",{resetOnDisable:true});
f.field("total").readonly().compute(m=>Math.round(m.subtotal*(1-m.discount/100)*100)/100).warning(m=>m.total<=100000,"Крупный заказ: менеджер свяжется для подтверждения");
f.field("paymentMethod").options([{value:"card",label:"Картой онлайн"},{value:"cash",label:"При получении"},{value:"invoice",label:"По счёту"}]).component("RadioGroup").initial("card").required("Выберите способ оплаты").check(m=>m.paymentMethod!=="invoice"||m.customerType==="company","Оплата по счёту — только для юридических лиц").setOnChange("customerType",m=>m.customerType==="person"&&m.paymentMethod==="invoice","card");
f.field("receiptEmail").email("Некорректный email для чека").sync("email");
f.field("comment").component("Textarea").maxLength(500,"Не больше 500 символов");
f.field("agreeTerms").required("Нужно принять условия оферты");
f.field("newsletter").component("Switch");
f.field("sources").component("SelectMulti").options([{value:"search",label:"Поиск"},{value:"friends",label:"Друзья"},{value:"ads",label:"Реклама"},{value:"other",label:"Другое"}]);
const it=f.array("items","Товары",{min:1,max:10});
it.min(1,"Добавьте хотя бы один товар");
f.field("items").maxLength(10,"Не больше 10 товаров");
it.column("title").required("Введите наименование");
it.column("quantity").initial(1).required("Укажите количество").rule("integer()","Количество — целое число").min(1,"Минимум 1").max(99,"Максимум 99");
it.column("price").required("Укажите цену").min(0,"Цена не может быть отрицательной");
it.column("lineTotal").readonly().compute(r=>(Number(r.quantity)||0)*(Number(r.price)||0));
const rc=f.array("recipients","Кому отправлять уведомления");
rc.column("email").required("Введите email получателя").email("Некорректный email получателя");
rc.column("primary").exclusive();
f.step("Покупатель").fields("customerType","contact.lastName","contact.firstName","email","phone","birthDate");
f.step("Компания").fields("company.name","company.inn").showWhen(m=>m.customerType==="company");
f.step("Доставка").fields("deliveryMethod","deliveryAddress.city","deliveryAddress.street","deliveryAddress.house","deliveryDate","billingSame","billingAddress.city","billingAddress.street","billingAddress.house");
f.step("Товары").fields("items","subtotal");
f.step("Оплата").fields("promoCode","discount","total","paymentMethod","receiptEmail","comment");
f.step("Подтверждение").fields("recipients","agreeTerms","newsletter","sources");
f.submit("Оформить заказ","submitOrder");
console.log(await f.save())

